# Bank zadań autorskich — partia 3: nowożytność (XVI–XVII w.).
# B(tytuł, materiał, *zadania) — wiązka; T(typ, punkty, polecenie, odpowiedź, omówienie) — zadanie.
BANK = {}

BANK['nowozytnosc'] = [
 B('Podział świata między Hiszpanię i Portugalię',
   'Tekst (autorski). W 1494 r. władcy dwóch państw iberyjskich, za pośrednictwem papieża, ustalili linię biegnącą z północy na południe przez Atlantyk, ok. 370 lig (ok. 2 tys. km) na zachód od Wysp Zielonego Przylądka. Ziemie odkryte na zachód od niej miały należeć do jednego państwa, a na wschód — do drugiego.',
   T('abcd', 1, 'Dokończ zdanie. Układ opisany w tekście to\nA. traktat w Saragossie.\nB. traktat w Tordesillas.\nC. bulla Inter caetera.\nD. pokój w Utrechcie.',
     'B',
     'Bulla Inter caetera (1493) wyznaczyła pierwszą linię, ale Portugalia jej nie zaakceptowała — w 1494 r. w Tordesillas przesunięto ją dalej na zachód. Traktat w Saragossie (1529) dotyczył Pacyfiku i Moluków, a pokój w Utrechcie to 1713 r.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy postanowienia układu tłumaczą, dlaczego w Brazylii mówi się dziś po portugalsku. Uzasadnij.',
     'Tak — wschodnia część Ameryki Południowej znalazła się na wschód od linii, czyli w strefie portugalskiej; po jej odkryciu (1500 r., Cabral) Portugalia ją skolonizowała.',
     'To dobry przykład, jak decyzja sprzed pięciuset lat wyjaśnia współczesną mapę językową. Reszta Ameryki Łacińskiej leżała w strefie hiszpańskiej.')),

 B('Handel trójkątny',
   'Schemat (autorski). Statki z portów Europy wiozły do Afryki Zachodniej broń, tkaniny i alkohol. Stamtąd płynęły przez Atlantyk z ludźmi porwanymi w niewolę. W Ameryce zabierały cukier, tytoń i bawełnę z plantacji i wracały do Europy.',
   T('wyjasnij', 1, 'Wyjaśnij, dlaczego europejskie kolonie w Ameryce potrzebowały niewolników z Afryki.',
     'Plantacje trzciny cukrowej, tytoniu i bawełny wymagały ogromnej siły roboczej, a ludność indiańska wymarła w dużej części z powodu chorób przywleczonych z Europy i przymusowej pracy.',
     'Pełna odpowiedź łączy dwa czynniki: zapotrzebowanie plantacji na pracę i katastrofę demograficzną Indian (ospa, odra, praca w kopalniach).'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Handel trójkątny łączył Europę, Afrykę i Amerykę.\n2. Głównym towarem wywożonym z Ameryki do Europy byli niewolnicy.\n3. Na handlu trójkątnym bogaciły się m.in. porty Wielkiej Brytanii i Francji.',
     '1 – P, 2 – F, 3 – P.',
     'Niewolników przewożono z Afryki do Ameryki, a z Ameryki do Europy płynęły produkty plantacji (cukier, tytoń, bawełna).')),

 B('„Książę”',
   'Tekst (autorski, na podstawie poglądów Niccolò Machiavellego). Władca, który chce utrzymać państwo, nie może zawsze postępować dobrze. Lepiej, by poddani się go bali, niż by go kochali, jeśli nie da się mieć obu tych rzeczy naraz. Dotrzymywanie słowa jest godne pochwały, ale mądry władca nie dotrzyma go, jeśli zaszkodziłoby to państwu.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy poglądy z tekstu są zgodne ze średniowiecznym ideałem władcy chrześcijańskiego. Uzasadnij.',
     'Nie — autor oddziela politykę od moralności: dopuszcza łamanie słowa i rządy oparte na strachu, jeśli służą państwu. Ideał średniowieczny wymagał od władcy cnót chrześcijańskich (sprawiedliwości, wierności, pobożności).',
     'Machiavelli („Książę”, 1513/1532) uznawany jest za twórcę realizmu politycznego. Hasło „cel uświęca środki” to uproszczenie — w zadaniach lepiej pisać o oddzieleniu polityki od etyki.'),
   T('abcd', 1, 'Dokończ zdanie. Twórcą poglądów przedstawionych w tekście był myśliciel związany z\nA. Florencją.\nB. Wenecją.\nC. Rzymem papieskim.\nD. Mediolanem Sforzów.',
     'A',
     'Machiavelli był sekretarzem Republiki Florenckiej, a „Księcia” zadedykował Medyceuszom. Wszystkie odpowiedzi to ważne ośrodki włoskiego renesansu, dlatego trzeba znać biografię autora.')),

 B('Mikołaj Kopernik',
   'Tekst (autorski). Astronom z Warmii twierdził, że w środku świata spoczywa Słońce, a Ziemia, tak jak inne planety, krąży wokół niego i dodatkowo obraca się wokół własnej osi. Swoje dzieło wydał w roku śmierci.',
   T('podaj', 1, 'Podaj nazwę teorii opisanej w tekście oraz nazwę teorii, którą ona zastąpiła.',
     'Teoria heliocentryczna zastąpiła teorię geocentryczną (Ptolemeusza).',
     'Dzieło „O obrotach sfer niebieskich” ukazało się w 1543 r. Kopernik był też ekonomistą (prawo o wypieraniu lepszego pieniądza przez gorszy) i administratorem dóbr kapituły warmińskiej.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy dzieło Kopernika wpisuje się w antropocentryzm renesansu. Uzasadnij.',
     'Tak — Kopernik oparł swoje wnioski na obserwacji i rozumowaniu, a nie wyłącznie na autorytecie tradycji; renesans cenił ludzki rozum i zdolność poznawania świata.',
     'Uwaga na pułapkę: heliocentryzm „przesuwa” człowieka ze środka wszechświata, ale antropocentryzm renesansu dotyczy wiary w możliwości człowieka, a nie położenia Ziemi. Liczy się argument o roli rozumu i obserwacji.')),

 B('Reformacja w Rzeszy',
   'Tekst (autorski). W 1555 r. w Augsburgu przedstawiciele katolickich i luterańskich stanów Rzeszy zawarli pokój religijny. Ustalono, że o wyznaniu poddanych decyduje władca danego terytorium, a ci, którzy nie chcą się podporządkować, mogą wyemigrować.',
   T('podaj', 1, 'Podaj łacińską zasadę, która streszcza postanowienie opisane w tekście.',
     'Cuius regio, eius religio („czyje panowanie, tego religia”).',
     'Zasada nie obejmowała kalwinistów — uznano ich dopiero w pokoju westfalskim (1648).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy pokój augsburski wprowadzał wolność wyznania dla każdego mieszkańca Rzeszy. Uzasadnij.',
     'Nie — o wyznaniu decydował władca terytorium, a poddani mogli jedynie wyemigrować; wolność wyboru miał władca, a nie jednostka.',
     'Porównaj z konfederacją warszawską (1573), która gwarantowała pokój między wyznaniami szlachcie, oraz z edyktem nantejskim (1598) we Francji.')),

 B('Francja w czasie wojen religijnych',
   'Tekst (autorski). Król, który sam przeszedł z kalwinizmu na katolicyzm, by zdobyć Paryż, wydał w 1598 r. edykt. Hugenoci otrzymali prawo do wyznawania swojej religii w określonych miejscach, równy dostęp do urzędów i twierdze jako gwarancję bezpieczeństwa.',
   T('abcd', 1, 'Dokończ zdanie. Władcą opisanym w tekście był\nA. Henryk Walezy (Henryk III).\nB. Henryk IV Burbon.\nC. Ludwik XIII.\nD. Karol IX.',
     'B',
     'Henryk IV („Paryż wart jest mszy”) wydał edykt nantejski. Karol IX panował w czasie nocy św. Bartłomieja (1572), Henryk Walezy był wcześniej królem Polski (1573–1574), a Ludwik XIII z kardynałem Richelieu odebrał hugenotom twierdze (La Rochelle, 1628).'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Edykt nantejski zakończył wojny religijne we Francji.\n2. Edykt nantejski uczynił kalwinizm religią państwową Francji.\n3. Ludwik XIV odwołał edykt nantejski w 1685 r.',
     '1 – P, 2 – F, 3 – P.',
     'Katolicyzm pozostał religią panującą; hugenoci dostali tolerancję, a nie równouprawnienie wyznania. Odwołanie edyktu (edykt z Fontainebleau) wywołało emigrację hugenotów, m.in. do Prus.')),

 B('Wojna trzydziestoletnia',
   'Tekst (autorski). Wojna zaczęła się w 1618 r. od wyrzucenia przez okno zamku na Hradczanach cesarskich namiestników. Z konfliktu religijnego w Czechach przerodziła się w wojnę o hegemonię w Europie, w której katolicka Francja walczyła po stronie protestantów przeciw Habsburgom.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy udział Francji w wojnie miał przede wszystkim przyczyny religijne. Uzasadnij, odwołując się do tekstu.',
     'Nie — katolicka Francja walczyła po stronie protestantów, bo jej celem było osłabienie Habsburgów i zdobycie przewagi w Europie, a nie obrona wiary.',
     'Kardynał Richelieu — premier katolickiej Francji — to klasyczny przykład racji stanu ważniejszej od religii.'),
   T('abcd', 1, 'Dokończ zdanie. Na mocy pokoju westfalskiego (1648)\nA. uznano niepodległość Zjednoczonych Prowincji Niderlandów i Szwajcarii.\nB. Habsburgowie przejęli koronę Francji.\nC. przywrócono jedność religijną Rzeszy pod przewodnictwem cesarza.\nD. Szwecja straciła wszystkie posiadłości w Rzeszy.',
     'A',
     'Pokój westfalski uznał niepodległość Niderlandów i Szwajcarii, zrównał kalwinistów z luteranami i katolikami, a Szwecja zyskała ziemie w Rzeszy (m.in. Pomorze Przednie). Rzesza została jeszcze bardziej rozbita.')),

 B('Hołd pruski',
   'Tekst (autorski). W 1525 r. na krakowskim rynku ostatni wielki mistrz zakonu krzyżackiego w Prusach złożył hołd królowi polskiemu jako świecki książę. Zakon w Prusach przestał istnieć, a jego dawny zwierzchnik przyjął luteranizm.',
   T('abcd', 1, 'Dokończ zdanie. Hołd opisany w tekście złożył\nA. Albrecht Hohenzollern.\nB. Fryderyk Wilhelm, Wielki Elektor.\nC. Ulrich von Jungingen.\nD. Albrecht Fryderyk.',
     'A',
     'Albrecht Hohenzollern przyjął hołd przed Zygmuntem Starym. Ulrich von Jungingen zginął pod Grunwaldem (1410), Albrecht Fryderyk był jego synem, a Fryderyk Wilhelm uzyskał niezależność Prus Książęcych od Polski (traktaty welawsko-bydgoskie, 1657).'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy decyzja króla polskiego o pozostawieniu Prus jako lenna była korzystna dla Polski w perspektywie XVII w. Uzasadnij.',
     'Nie — Prusy pozostały w rękach Hohenzollernów, którzy połączyli je z Brandenburgią; w 1657 r. uniezależnili się od Polski, a później stały się jednym z zaborców.',
     'W 1525 r. hołd uważano za sukces (koniec zagrożenia krzyżackiego). Pytanie o perspektywę XVII w. wymaga dostrzeżenia skutków długofalowych.')),

 B('Ruch egzekucyjny',
   'Tekst (autorski, w duchu postulatów średniej szlachty z połowy XVI w.). Domagamy się, by przestrzegano praw już uchwalonych, a nie stanowiono nowych. Dobra królewskie rozdane magnatom niezgodnie z prawem muszą wrócić do skarbu. Trzeba też ściślej połączyć Koronę z Litwą i zbudować stałe wojsko, opłacane z dochodów państwa.',
   T('podaj', 1, 'Podaj nazwę ruchu politycznego szlachty, którego postulaty przedstawia tekst.',
     'Ruch egzekucyjny (egzekucja praw i dóbr).',
     'Nazwa pochodzi od „egzekwowania” (wykonania) istniejących praw.'),
   T('abcd', 1, 'Dokończ zdanie. Jednym z efektów ruchu opisanego w tekście było\nA. utworzenie wojska kwarcianego.\nB. wprowadzenie wolnej elekcji.\nC. uchwalenie konstytucji Nihil novi.\nD. zawarcie unii w Krewie.',
     'A',
     'Sejm w Piotrkowie (1562–1563) postanowił, że czwartą część („kwartę”) dochodów z królewszczyzn przeznacza się na stałe wojsko — wojsko kwarciane. Nihil novi to rok 1505, unia w Krewie — 1385, wolna elekcja — po 1572 r.')),

 B('Elekcja Henryka Walezego',
   'Tekst (autorski). Przed koronacją nowy król musiał zaprzysiąc dwa rodzaje zobowiązań. Pierwsze były stałe i obowiązywały każdego kolejnego władcę: wolna elekcja, zwoływanie sejmu co dwa lata, tolerancja religijna, prawo do wypowiedzenia posłuszeństwa. Drugie dotyczyły osobistych obietnic tego konkretnego kandydata.',
   T('podaj', 1, 'Podaj nazwy obu rodzajów zobowiązań opisanych w tekście.',
     'Artykuły henrykowskie (stałe) i pacta conventa (osobiste zobowiązania elekta).',
     'Artykuły henrykowskie podpisywał każdy kolejny król, pacta conventa były negocjowane przy każdej elekcji osobno.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy postanowienia opisane w tekście wzmacniały władzę królewską. Uzasadnij.',
     'Nie — ograniczały ją: król musiał regularnie zwoływać sejm, nie mógł wybrać następcy, a szlachta zyskała prawo wypowiedzenia mu posłuszeństwa (de non praestanda oboedientia).',
     'To fundament „demokracji szlacheckiej”: monarchia elekcyjna z silnym sejmem i słabym królem.')),

 B('Wojny z Moskwą na początku XVII w.',
   'Tekst (autorski). W 1610 r. hetman polny koronny rozbił pod Kłuszynem kilkakrotnie liczniejszą armię rosyjsko-szwedzką. Bojarzy moskiewscy obrali wkrótce carem syna króla polskiego, a polska załoga wkroczyła na Kreml.',
   T('abcd', 1, 'Dokończ zdanie. Zwycięzcą spod Kłuszyna był\nA. Jan Karol Chodkiewicz.\nB. Stanisław Żółkiewski.\nC. Stanisław Koniecpolski.\nD. Stefan Czarniecki.',
     'B',
     'Chodkiewicz zwyciężył Szwedów pod Kircholmem (1605), Koniecpolski — Szwedów i Tatarów w latach 20.–30. XVII w., Czarniecki walczył w czasie potopu. Żółkiewski zginął później pod Cecorą (1620).'),
   T('podaj', 1, 'Podaj imię syna króla polskiego obranego carem.',
     'Władysław (późniejszy Władysław IV Waza).',
     'Zygmunt III chciał tronu carskiego dla siebie i nie zgodził się na przejście Władysława na prawosławie — szansa na unię z Moskwą przepadła.'),
   T('uporzadkuj', 1, 'Uporządkuj chronologicznie wydarzenia.\nA. bitwa pod Kircholmem\nB. rozejm w Dywilinie\nC. bitwa pod Kłuszynem\nD. bitwa pod Chocimiem z Turkami',
     'A, C, B, D.',
     'Kircholm: 1605 → Kłuszyn: 1610 → Dywilino (rozejm z Moskwą, Polska zyskuje ziemię smoleńską): 1618/1619 → Chocim: 1621.')),

 B('Unia brzeska',
   'Tekst (autorski). W 1596 r. część biskupów prawosławnych Rzeczypospolitej uznała zwierzchnictwo papieża i przyjęła katolickie dogmaty, zachowując wschodni obrządek i język liturgii. Innym duchownym i wiernym ta decyzja się nie spodobała i zostali przy prawosławiu.',
   T('podaj', 1, 'Podaj nazwę Kościoła, który powstał w wyniku wydarzenia opisanego w tekście.',
     'Kościół unicki (greckokatolicki).',
     'Unia brzeska podzieliła prawosławnych Rzeczypospolitej — spór między unitami a prawosławnymi zaostrzył konflikty na Ukrainie i stał się jedną z przyczyn powstania Chmielnickiego.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Unię zawarto za panowania Zygmunta III Wazy.\n2. Unici przyjęli łacinę jako język liturgii.\n3. Unia była częścią działań kontrreformacji.',
     '1 – P, 2 – F, 3 – P.',
     'Unici zachowali liturgię w języku cerkiewnosłowiańskim i obrządek wschodni (np. żonatych księży).')),

 B('Myśl polityczna polskiego renesansu',
   'Tekst (autorski, na podstawie poglądów jednego z pisarzy polskiego odrodzenia). Prawo powinno być jednakowe dla wszystkich stanów. Za zabójstwo chłopa szlachcic powinien ponieść taką samą karę, jak za zabójstwo szlachcica. Urzędy trzeba powierzać ludziom zdolnym i uczonym, a nie tylko urodzonym w możnych rodach.',
   T('abcd', 1, 'Dokończ zdanie. Poglądy przedstawione w tekście głosił\nA. Mikołaj Rej.\nB. Andrzej Frycz Modrzewski.\nC. Piotr Skarga.\nD. Jan Kochanowski.',
     'B',
     'Modrzewski („O poprawie Rzeczypospolitej”) postulował równość wobec prawa. Skarga w „Kazaniach sejmowych” bronił silnej władzy króla i Kościoła, Rej pisał o życiu ziemiańskim, Kochanowski — poezję.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy postulat z tekstu odpowiadał ówczesnemu prawu Rzeczypospolitej. Uzasadnij.',
     'Nie — ówczesne prawo przewidywało za zabójstwo chłopa przez szlachcica jedynie grzywnę (główszczyznę), a nie karę śmierci; przywileje szlacheckie nie dawały chłopom równej ochrony.',
     'W Rzeczypospolitej XVI w. obowiązywało prawo stanowe — każdy stan miał inne prawa i sądy. Modrzewski był pod tym względem wyjątkowo nowoczesny.')),
]
